parameters.jsCode:
const response = $input.first().json;
const text = response.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

try {
  return JSON.parse(text);
} catch (e) {
  // Fallback parsing
  return {
    intent: text.includes('rechnung') ? 'rechnung_erinnerung' : 'termin_erinnerung',
    kunde: 'Unbekannt',
    details: '',
    dringlichkeit: 'normal'
  };
}

const kunde = $input.first().json;
const intent = $('Code: Intent parsen').first().json;

// ElevenLabs Conversational AI 2.0 Konfiguration
const agentConfig = {
  conversation: {
    tts: {
      voice_id: 'XB0fDUnXU5powFXDhCwa', // Anna (German professional)
      model_id: 'eleven_turbo_v2_5'       // Fastest model
    },
    llm: {
      provider: 'google',
      model: 'gemini-2.5-flash',
      temperature: 0.7
    },
    language_detection: true,
    turn_taking: { mode: 'natural' }
  }
};

let systemPrompt = '';
let firstMessage = '';

if (intent.intent === 'rechnung_erinnerung') {
  const urgencyStyle = {
    'freundlich': 'Sei besonders freundlich und verständnisvoll.',
    'normal': 'Sei professionell und freundlich.',
    'dringend': 'Sei höflich aber bestimmt. Betone die Dringlichkeit.'
  };

  systemPrompt = `Du bist ein Telefonassistent für Rechnungserinnerungen.
${urgencyStyle[intent.dringlichkeit] || urgencyStyle.normal}

Kundeninformationen:
- Name: ${kunde.name}
- Rechnungsnummer: ${kunde.invoice_number}
- Betrag: ${kunde.amount} €
- Fälligkeitsdatum: ${new Date(kunde.due_date).toLocaleDateString('de-DE')}

Deine Aufgabe:
1. Begrüße den Kunden höflich
2. Erkläre den Grund des Anrufs (offene Rechnung)
3. Frage nach dem voraussichtlichen Zahlungstermin
4. Beantworte Fragen zur Rechnung
5. Bedanke dich und verabschiede dich

Wichtig:
- Sprich natürlich und nicht roboterhaft
- Halte Antworten kurz (max 2-3 Sätze)
- Bei Problemen: biete Rückruf durch Mitarbeiter an`;

  firstMessage = `Guten Tag, hier spricht der automatische Assistent. Spreche ich mit ${kunde.name}?`;

} else {
  systemPrompt = `Du bist ein Telefonassistent für Terminerinnerungen.
Sei freundlich und hilfsbereit.

Termininformationen:
- Kunde: ${kunde.name}
- Datum: ${new Date(kunde.appointment_date).toLocaleDateString('de-DE')}
- Uhrzeit: ${kunde.appointment_time}
${kunde.location ? '- Ort: ' + kunde.location : ''}
${kunde.description ? '- Betreff: ' + kunde.description : ''}

Deine Aufgabe:
1. Begrüße den Kunden höflich
2. Erinnere an den bevorstehenden Termin
3. Bitte um Bestätigung oder frage nach Änderungswünschen
4. Bei Absage: biete Alternativtermin an
5. Bedanke dich und verabschiede dich`;

  firstMessage = `Guten Tag, hier spricht der automatische Terminservice. Spreche ich mit ${kunde.name}?`;
}

agentConfig.conversation.llm.system_prompt = systemPrompt;
agentConfig.conversation.first_message = firstMessage;

// Tools für den Agenten
agentConfig.conversation.tools = [
  {
    name: 'record_outcome',
    description: 'Notiert das Ergebnis des Gesprächs',
    parameters: {
      type: 'object',
      properties: {
        outcome: {
          type: 'string',
          enum: ['zahlung_zugesagt', 'termin_bestaetigt', 'rueckruf_gewuenscht', 'abgelehnt']
        },
        details: { type: 'string' },
        follow_up_date: { type: 'string' }
      },
      required: ['outcome']
    }
  }
];

return {
  kunde_id: kunde.id,
  kunde_name: kunde.name,
  kunde_phone: kunde.phone,
  kunde_email: kunde.email,
  intent: intent.intent,
  dringlichkeit: intent.dringlichkeit,
  agent_config: agentConfig,
  raw_data: kunde
};

